scripts.crt_solver:
def solve(inputs: dict) -> float:
    """
    Solve system of modular equations using Chinese Remainder Theorem
    x ≡ a_i (mod m_i) for each i
    """
    remainders = inputs.get('remainders')
    moduli = inputs.get('moduli')

    if isinstance(remainders, list):
        rems = remainders
    else:
        rems = list(remainders) if hasattr(remainders, '__iter__') else [remainders]

    if isinstance(moduli, list):
        mods = moduli
    else:
        mods = list(moduli) if hasattr(moduli, '__iter__') else [moduli]

    # Extended GCD
    def extended_gcd(a, b):
        if a == 0:
            return b, 0, 1
        gcd, x1, y1 = extended_gcd(b % a, a)
        x = y1 - (b // a) * x1
        y = x1
        return gcd, x, y

    # Modular inverse
    def mod_inverse(a, m):
        gcd, x, _ = extended_gcd(a % m, m)
        if gcd != 1:
            raise ValueError("Modular inverse does not exist")
        return (x % m + m) % m

    # CRT for two equations
    def crt_two(a1, m1, a2, m2):
        gcd, p, q = extended_gcd(m1, m2)
        if gcd != 1:
            raise ValueError("Moduli are not coprime")
        lcm = m1 * m2 // gcd
        x = (a1 + m1 * p * ((a2 - a1) // gcd)) % lcm
        return x, lcm

    # Apply CRT iteratively
    x = rems[0]
    m = mods[0]

    for i in range(1, len(rems)):
        x, m = crt_two(x, m, rems[i], mods[i])

    return float(x)
